  "títulos": "titres",
  "subtítulo": "sous-titre",
  "El episodio {episode} tiene {count} pistas de audio y el primero tiene {first}. dvdauthor usa el layout del primer título.": "L’épisode {episode} a {count} pistes audio et le premier en a {first}. dvdauthor utilise la disposition du premier titre.",
  "El episodio {episode} referencia audio externo; el encoder usa el stream embebido del vídeo.": "L’épisode {episode} référence un audio externe ; l’encodeur utilise le flux intégré à la vidéo.",
  "El episodio {episode} tiene subtítulos internos; se extraerán del vídeo con FFmpeg antes de multiplexarlos.": "L’épisode {episode} a des sous-titres internes ; ils seront extraits de la vidéo avec FFmpeg avant le multiplexage.",
  "Se activó Half-D1 automáticamente: duración {duration} ms y bitrate calculado {bitrate} kbps.": "Half-D1 a été activé automatiquement : durée {duration} ms et débit calculé {bitrate} kbps.",
  "El bitrate calculado {bitrate} kbps supera el máximo {max} kbps; el disco quedará por debajo del objetivo de llenado.": "Le débit calculé {bitrate} kbps dépasse le maximum {max} kbps ; le disque restera sous l’objectif de remplissage.",
  "D1 está forzado pero el bitrate calculado ({bitrate} kbps) es inferior a {min} kbps.": "D1 est forcé mais le débit calculé ({bitrate} kbps) est inférieur à {min} kbps.",
  "El episodio {episode} se limita a {bitrate} kbps para respetar el máximo total de DVD con sus pistas de audio.": "L’épisode {episode} est limité à {bitrate} kbps pour respecter le maximum total DVD avec ses pistes audio.",
  "El plan solo llena el {percent}% de la capacidad efectiva; el contenido es demasiado corto para alcanzar el 99% sin superar el bitrate máximo.": "Le plan ne remplit que {percent}% de la capacité effective ; le contenu est trop court pour atteindre 99% sans dépasser le débit maximal.",
  "El plan no es viable con el perfil y presupuesto actuales.": "Le plan n’est pas viable avec le profil et le budget actuels.",
  "Los subtítulos externos de AVCHD/Blu-ray se conservan en el proyecto, pero todavía no se multiplexan en la imagen.": "Les sous-titres externes AVCHD/Blu-ray sont conservés dans le projet mais ne sont pas encore multiplexés dans l’image.",
  "El episodio {episode} tiene varias pistas de audio; AVCHD usará la primera.": "L’épisode {episode} a plusieurs pistes audio ; AVCHD utilisera la première.",
  "El bitrate calculado {bitrate} kbps supera el máximo de {max} kbps para {capacity}; el disco quedará por debajo del objetivo de llenado.": "Le débit calculé {bitrate} kbps dépasse le maximum de {max} kbps pour {capacity} ; le disque restera sous l’objectif de remplissage.",
  "Más de 5 horas de contenido: considera resolución SD para conservar calidad y capacidad.": "Plus de 5 heures de contenu : envisagez la résolution SD pour préserver la qualité et la capacité.",
  "El plan llena el {percent}% de la capacidad efectiva de {capacity}; el contenido es demasiado corto para aprovecharla.": "Le plan remplit {percent}% de la capacité effective de {capacity} ; le contenu est trop court pour en profiter.",
  "El plan AVCHD supera el presupuesto del disco.": "Le plan AVCHD dépasse le budget du disque.",
  "El First Play referencia un asset inexistente; no se reserva espacio para la intro.": "Le First Play référence un asset inexistant ; aucun espace n’est réservé pour l’intro.",
