  "No se pudo componer «{menu}»: {error}": "Impossible de composer « {menu} » : {error}",
  "AVCHD usa reproducción continua; las plantillas de menú no aplican.": "AVCHD utilise la lecture continue ; les modèles de menu ne s’appliquent pas.",
  "AVCHD/Blu-ray usa H.264, AC-3 y menús HDMV Interactive Graphics. Puedes elegir BD-25 o BD-50 en la cabecera para habilitar el authoring Blu-ray nativo.": "AVCHD/Blu-ray utilise H.264, AC-3 et des menus HDMV Interactive Graphics. Choisissez BD-25 ou BD-50 dans l’en-tête pour activer l’authoring Blu-ray natif.",
  "Activa el menú animado para editar el bucle y los fundidos.": "Activez le menu animé pour modifier la boucle et les fondus.",
  "Alineado a bloques ECC de 16 sectores. La autoría ajusta el corte de capa al PGC más cercano durante la grabación.": "Aligné sur des blocs ECC de 16 secteurs. L’authoring ajuste le point de changement de couche au PGC le plus proche lors de la gravure.",
  "Arrastra para mover · tiradores para redimensionar · coordenadas pares y separación mínima de 4 px.": "Faites glisser pour déplacer · poignées pour redimensionner · coordonnées paires et écart minimal de 4 px.",
  "Añade un menú al proyecto o abre la pestaña Menú desde un proyecto Blu-ray/AVCHD.": "Ajoutez un menu au projet ou ouvrez l’onglet Menu depuis un projet Blu-ray/AVCHD.",
  "Añade un vídeo desde la biblioteca de medios o elige un episodio en la secuencia.": "Ajoutez une vidéo depuis la bibliothèque de médias ou choisissez un épisode dans la séquence.",
  "Buffer underflow probable: reduce la prioridad de los episodios largos o cambia a Half-D1 / DVD-9.": "Buffer underflow probable : réduisez la priorité des épisodes longs ou passez à Half-D1 / DVD-9.",
  "Comprueba las herramientas externas que usan DVD, AVCHD y Blu-ray.": "Vérifie les outils externes utilisés par DVD, AVCHD et Blu-ray.",
  "Crea o abre un proyecto para importar medios.": "Créez ou ouvrez un projet pour importer des médias.",
  "Crea un menú para configurar su bucle, fundidos y botones de vídeo en DVD o HD.": "Créez un menu pour configurer sa boucle, ses fondus et ses boutons vidéo en DVD ou HD.",
  "Crea un proyecto DVD-Video o Blu-ray/AVCHD para probar la navegación interactiva.": "Créez un projet DVD-Video ou Blu-ray/AVCHD pour tester la navigation interactive.",
  "Crea un proyecto DVD-Video para ver el flujo de la máquina virtual.": "Créez un projet DVD-Video pour voir le flux de la machine virtuelle.",
  "DVD-Video admite hasta 8 pistas de audio y 32 subimágenes; AVCHD y Blu-ray priorizan la primera pista AC-3. Mantén una pista como predeterminada y usa desfases de ±10 s para corregir desincronizaciones.": "DVD-Video prend en charge jusqu’à 8 pistes audio et 32 sous-images ; AVCHD et Blu-ray privilégient la première piste AC-3. Gardez une piste par défaut et utilisez des décalages de ±10 s pour corriger les désynchronisations.",
  "DVD-Video universal o AVCHD/Blu-ray HD con menús HDMV interactivos.": "DVD-Video universel ou AVCHD/Blu-ray HD avec menus HDMV interactifs.",
  "El clip se repite en bucle y se codifica en el menú HD o DVD animado.": "Le clip boucle et est encodé dans le menu HD ou DVD animé.",
  "El menú estático se muestra indefinidamente. Actívalo para definir un bucle con entrada/salida y música.": "Le menu statique s’affiche indéfiniment. Activez-le pour définir une boucle avec points d’entrée/sortie et musique.",
  "El plan se calculará automáticamente al generar el disco.": "Le plan sera calculé automatiquement lors de la création du disque.",
