  "El simulador usa el grafo de navegación calculado por Rust, incluidos los overrides del inspector y las acciones de cada botón.": "Le simulateur utilise le graphe de navigation calculé par Rust, y compris les remplacements de l’inspecteur et les actions de chaque bouton.",
  "Elige un episodio en la secuencia para editar sus pistas de audio y subtítulos.": "Choisissez un épisode dans la séquence pour modifier ses pistes audio et sous-titres.",
  "Este proyecto AVCHD no tiene menús y se reproduce en continuo. Añade un menú para compilar Interactive Graphics HDMV.": "Ce projet AVCHD n’a pas de menus et est lu en continu. Ajoutez un menu pour compiler Interactive Graphics HDMV.",
