  "La duración del menú se sincroniza con el proyecto. La composición combina el fondo, la música y los fragmentos de vídeo de los botones.": "La durée du menu est synchronisée avec le projet. La composition combine l’arrière-plan, la musique et les fragments vidéo des boutons.",
