  "El episodio {episode} tiene {count} pistas de audio y el primero tiene {first}. dvdauthor usa el layout del primer título.": "Episode {episode} hat {count} Audiospuren und die erste hat {first}. dvdauthor verwendet das Layout des ersten Titels.",
  "El episodio {episode} referencia audio externo; el encoder usa el stream embebido del vídeo.": "Episode {episode} verweist auf externes Audio; der Encoder verwendet den eingebetteten Stream des Videos.",
  "El episodio {episode} tiene subtítulos internos; se extraerán del vídeo con FFmpeg antes de multiplexarlos.": "Episode {episode} hat interne Untertitel; sie werden vor dem Multiplexen mit FFmpeg aus dem Video extrahiert.",
  "Se activó Half-D1 automáticamente: duración {duration} ms y bitrate calculado {bitrate} kbps.": "Half-D1 wurde automatisch aktiviert: Dauer {duration} ms und berechnete Bitrate {bitrate} kbps.",
  "El bitrate calculado {bitrate} kbps supera el máximo {max} kbps; el disco quedará por debajo del objetivo de llenado.": "Die berechnete Bitrate {bitrate} kbps überschreitet das Maximum von {max} kbps; die Disc bleibt unter dem Füllziel.",
  "D1 está forzado pero el bitrate calculado ({bitrate} kbps) es inferior a {min} kbps.": "D1 ist erzwungen, aber die berechnete Bitrate ({bitrate} kbps) liegt unter {min} kbps.",
  "El episodio {episode} se limita a {bitrate} kbps para respetar el máximo total de DVD con sus pistas de audio.": "Episode {episode} ist auf {bitrate} kbps begrenzt, um das DVD-Gesamtmaximum mit ihren Audiospuren einzuhalten.",
  "El plan solo llena el {percent}% de la capacidad efectiva; el contenido es demasiado corto para alcanzar el 99% sin superar el bitrate máximo.": "Der Plan füllt nur {percent}% der effektiven Kapazität; der Inhalt ist zu kurz, um 99% zu erreichen, ohne die maximale Bitrate zu überschreiten.",
  "El plan no es viable con el perfil y presupuesto actuales.": "Der Plan ist mit dem aktuellen Profil und Budget nicht machbar.",
  "Los subtítulos externos de AVCHD/Blu-ray se conservan en el proyecto, pero todavía no se multiplexan en la imagen.": "Externe AVCHD/Blu-ray-Untertitel bleiben im Projekt erhalten, werden aber noch nicht in das Image gemultiplext.",
  "El episodio {episode} tiene varias pistas de audio; AVCHD usará la primera.": "Episode {episode} hat mehrere Audiospuren; AVCHD verwendet die erste.",
  "El bitrate calculado {bitrate} kbps supera el máximo de {max} kbps para {capacity}; el disco quedará por debajo del objetivo de llenado.": "Die berechnete Bitrate {bitrate} kbps überschreitet das Maximum von {max} kbps für {capacity}; die Disc bleibt unter dem Füllziel.",
  "Más de 5 horas de contenido: considera resolución SD para conservar calidad y capacidad.": "Mehr als 5 Stunden Inhalt: Erwägen Sie SD-Auflösung, um Qualität und Kapazität zu erhalten.",
  "El plan llena el {percent}% de la capacidad efectiva de {capacity}; el contenido es demasiado corto para aprovecharla.": "Der Plan füllt {percent}% der effektiven Kapazität von {capacity}; der Inhalt ist zu kurz, um sie zu nutzen.",
  "El plan AVCHD supera el presupuesto del disco.": "Der AVCHD-Plan überschreitet das Disc-Budget.",
