  "No se pudo componer «{menu}»: {error}": "„{menu}“ konnte nicht zusammengesetzt werden: {error}",
  "AVCHD usa reproducción continua; las plantillas de menú no aplican.": "AVCHD verwendet die kontinuierliche Wiedergabe; Menüvorlagen gelten nicht.",
  "AVCHD/Blu-ray usa H.264, AC-3 y menús HDMV Interactive Graphics. Puedes elegir BD-25 o BD-50 en la cabecera para habilitar el authoring Blu-ray nativo.": "AVCHD/Blu-ray verwendet H.264, AC-3 und HDMV Interactive Graphics-Menüs. Wählen Sie BD-25 oder BD-50 in der Kopfzeile, um natives Blu-ray-Authoring zu aktivieren.",
  "Activa el menú animado para editar el bucle y los fundidos.": "Aktivieren Sie das animierte Menü, um Schleife und Überblendungen zu bearbeiten.",
  "Alineado a bloques ECC de 16 sectores. La autoría ajusta el corte de capa al PGC más cercano durante la grabación.": "An 16-Sektor-ECC-Blöcke ausgerichtet. Beim Authoring wird der Layer Break beim Brennen am nächsten PGC ausgerichtet.",
  "Arrastra para mover · tiradores para redimensionar · coordenadas pares y separación mínima de 4 px.": "Ziehen zum Verschieben · Griffe zum Größenändern · gerade Koordinaten und mindestens 4 px Abstand.",
  "Añade un menú al proyecto o abre la pestaña Menú desde un proyecto Blu-ray/AVCHD.": "Fügen Sie dem Projekt ein Menü hinzu oder öffnen Sie die Registerkarte Menü aus einem Blu-ray/AVCHD-Projekt.",
  "Añade un vídeo desde la biblioteca de medios o elige un episodio en la secuencia.": "Fügen Sie ein Video aus der Medienbibliothek hinzu oder wählen Sie eine Episode in der Sequenz.",
  "Buffer underflow probable: reduce la prioridad de los episodios largos o cambia a Half-D1 / DVD-9.": "Wahrscheinlicher Buffer-Underflow: Reduzieren Sie die Priorität langer Episoden oder wechseln Sie zu Half-D1 / DVD-9.",
  "Comprueba las herramientas externas que usan DVD, AVCHD y Blu-ray.": "Prüft die externen Werkzeuge, die DVD, AVCHD und Blu-ray verwenden.",
  "Crea o abre un proyecto para importar medios.": "Erstellen oder öffnen Sie ein Projekt, um Medien zu importieren.",
  "Crea un menú para configurar su bucle, fundidos y botones de vídeo en DVD o HD.": "Erstellen Sie ein Menü, um Schleife, Überblendungen und Videotasten für DVD oder HD zu konfigurieren.",
  "Crea un proyecto DVD-Video o Blu-ray/AVCHD para probar la navegación interactiva.": "Erstellen Sie ein DVD-Video- oder Blu-ray/AVCHD-Projekt, um die interaktive Navigation zu testen.",
  "Crea un proyecto DVD-Video para ver el flujo de la máquina virtual.": "Erstellen Sie ein DVD-Video-Projekt, um den Ablauf der virtuellen Maschine zu sehen.",
  "DVD-Video admite hasta 8 pistas de audio y 32 subimágenes; AVCHD y Blu-ray priorizan la primera pista AC-3. Mantén una pista como predeterminada y usa desfases de ±10 s para corregir desincronizaciones.": "DVD-Video unterstützt bis zu 8 Audiospuren und 32 Unterbilder; AVCHD und Blu-ray bevorzugen die erste AC-3-Spur. Behalten Sie eine Spur als Standard und verwenden Sie ±10 s Verzögerungen, um Synchronisationsprobleme zu beheben.",
  "DVD-Video universal o AVCHD/Blu-ray HD con menús HDMV interactivos.": "Universelles DVD-Video oder HD-AVCHD/Blu-ray mit interaktiven HDMV-Menüs.",
  "El clip se repite en bucle y se codifica en el menú HD o DVD animado.": "Der Clip wird in einer Schleife wiedergegeben und in das HD- oder animierte DVD-Menü codiert.",
  "El menú estático se muestra indefinidamente. Actívalo para definir un bucle con entrada/salida y música.": "Das statische Menü wird unbegrenzt angezeigt. Aktivieren Sie es, um eine Schleife mit In/Out-Punkten und Musik festzulegen.",
  "El plan se calculará automáticamente al generar el disco.": "Der Plan wird beim Erstellen der Disc automatisch berechnet.",
  "El promedio global se mantiene; los bits se redistribuyen.": "Der Gesamtdurchschnitt bleibt erhalten; die Bits werden neu verteilt.",
  "El simulador usa el grafo de navegación calculado por Rust, incluidos los overrides del inspector y las acciones de cada botón.": "Der Simulator verwendet den von Rust berechneten Navigationsgraphen, einschließlich der Überschreibungen des Inspektors und der Aktionen jeder Schaltfläche.",
  "Elige un episodio en la secuencia para editar sus pistas de audio y subtítulos.": "Wählen Sie eine Episode in der Sequenz, um ihre Audio- und Untertitelspuren zu bearbeiten.",
  "Este proyecto AVCHD no tiene menús y se reproduce en continuo. Añade un menú para compilar Interactive Graphics HDMV.": "Dieses AVCHD-Projekt hat keine Menüs und wird kontinuierlich wiedergegeben. Fügen Sie ein Menü hinzu, um HDMV Interactive Graphics zu kompilieren.",
  "Este proyecto no tiene menús. Cambia a DVD-Video para diseñar uno.": "Dieses Projekt hat keine Menüs. Wechseln Sie zu DVD-Video, um eines zu gestalten.",
  "Flechas para navegar · Enter para activar · Retroceso para volver.": "Pfeiltasten zum Navigieren · Enter zum Aktivieren · Rücktaste zum Zurückgehen.",
  "Genera una composición completa a partir de los episodios y ajusta después en el lienzo.": "Erzeugen Sie eine vollständige Komposition aus den Episoden und passen Sie sie anschließend auf der Leinwand an.",
  "HD/SD continuo con capítulos para PS4, PS5 y Blu-ray.": "Kontinuierliches HD/SD mit Kapiteln für PS4, PS5 und Blu-ray.",
  "INICIO → VMGM → VTSM → títulos · clic en un nodo para inspeccionarlo": "START → VMGM → VTSM → Titel · Klicken Sie auf einen Knoten, um ihn zu prüfen",
  "INICIO, VMGM, VTSM y títulos. Las aristas discontinuas son comandos de retorno o «Reproducir todo».": "START, VMGM, VTSM und Titel. Gestrichelte Kanten sind Rücksprungbefehle oder „Alle abspielen“.",
  "Importa un vídeo desde la biblioteca para usarlo como fondo en bucle.": "Importieren Sie ein Video aus der Bibliothek, um es als Schleifenhintergrund zu verwenden.",
