  "La duración del menú se sincroniza con el proyecto. La composición combina el fondo, la música y los fragmentos de vídeo de los botones.": "Die Menüdauer wird mit dem Projekt synchronisiert. Die Komposition kombiniert Hintergrund, Musik und Videofragmente der Schaltflächen.",
  "La secuencia está vacía. Importa un vídeo y añádelo como episodio.": "Die Sequenz ist leer. Importieren Sie ein Video und fügen Sie es als Episode hinzu.",
  "Los episodios se reproducen en orden. No hay menú interactivo; usa la lista para empezar y los capítulos se respetan dentro de cada episodio.": "Die Episoden werden der Reihe nach abgespielt. Es gibt kein interaktives Menü; starten Sie über die Liste, und Kapitel werden innerhalb jeder Episode berücksichtigt.",
  "Los menús, el foco y la navegación siguen funcionando.": "Menüs, Fokus und Navigation funktionieren weiterhin.",
  "Líneas discontinuas: retornos automáticos o reproducir todo.": "Gestrichelte Linien: automatische Rücksprünge oder alle abspielen.",
  "Menús Konva, botones, capítulos y máxima compatibilidad.": "Konva-Menüs, Schaltflächen, Kapitel und maximale Kompatibilität.",
