  "subtítulo": "sottotitolo",
  "El episodio {episode} tiene {count} pistas de audio y el primero tiene {first}. dvdauthor usa el layout del primer título.": "L’episodio {episode} ha {count} tracce audio e il primo ne ha {first}. dvdauthor usa il layout del primo titolo.",
  "El episodio {episode} referencia audio externo; el encoder usa el stream embebido del vídeo.": "L’episodio {episode} fa riferimento ad audio esterno; l’encoder usa lo stream incorporato nel video.",
  "El episodio {episode} tiene subtítulos internos; se extraerán del vídeo con FFmpeg antes de multiplexarlos.": "L’episodio {episode} ha sottotitoli interni; saranno estratti dal video con FFmpeg prima del multiplexing.",
  "Se activó Half-D1 automáticamente: duración {duration} ms y bitrate calculado {bitrate} kbps.": "Half-D1 è stato attivato automaticamente: durata {duration} ms e bitrate calcolato {bitrate} kbps.",
  "El bitrate calculado {bitrate} kbps supera el máximo {max} kbps; el disco quedará por debajo del objetivo de llenado.": "Il bitrate calcolato {bitrate} kbps supera il massimo {max} kbps; il disco resterà sotto l’obiettivo di riempimento.",
  "D1 está forzado pero el bitrate calculado ({bitrate} kbps) es inferior a {min} kbps.": "D1 è forzato ma il bitrate calcolato ({bitrate} kbps) è inferiore a {min} kbps.",
  "El episodio {episode} se limita a {bitrate} kbps para respetar el máximo total de DVD con sus pistas de audio.": "L’episodio {episode} è limitato a {bitrate} kbps per rispettare il massimo totale DVD con le sue tracce audio.",
  "El plan solo llena el {percent}% de la capacidad efectiva; el contenido es demasiado corto para alcanzar el 99% sin superar el bitrate máximo.": "Il piano riempie solo il {percent}% della capacità effettiva; il contenuto è troppo breve per raggiungere il 99% senza superare il bitrate massimo.",
  "El plan no es viable con el perfil y presupuesto actuales.": "Il piano non è fattibile con il profilo e il budget attuali.",
  "Los subtítulos externos de AVCHD/Blu-ray se conservan en el proyecto, pero todavía no se multiplexan en la imagen.": "I sottotitoli esterni AVCHD/Blu-ray vengono mantenuti nel progetto ma non sono ancora multiplexati nell’immagine.",
  "El episodio {episode} tiene varias pistas de audio; AVCHD usará la primera.": "L’episodio {episode} ha più tracce audio; AVCHD userà la prima.",
  "El bitrate calculado {bitrate} kbps supera el máximo de {max} kbps para {capacity}; el disco quedará por debajo del objetivo de llenado.": "Il bitrate calcolato {bitrate} kbps supera il massimo di {max} kbps per {capacity}; il disco resterà sotto l’obiettivo di riempimento.",
  "Más de 5 horas de contenido: considera resolución SD para conservar calidad y capacidad.": "Più di 5 ore di contenuto: considera la risoluzione SD per preservare qualità e capacità.",
  "El plan llena el {percent}% de la capacidad efectiva de {capacity}; el contenido es demasiado corto para aprovecharla.": "Il piano riempie il {percent}% della capacità effettiva di {capacity}; il contenuto è troppo breve per sfruttarla.",
