  "AVCHD/Blu-ray usa H.264, AC-3 y menús HDMV Interactive Graphics. Puedes elegir BD-25 o BD-50 en la cabecera para habilitar el authoring Blu-ray nativo.": "AVCHD/Blu-ray usa H.264, AC-3 e menu HDMV Interactive Graphics. Scegli BD-25 o BD-50 nell’intestazione per abilitare l’authoring Blu-ray nativo.",
  "Activa el menú animado para editar el bucle y los fundidos.": "Attiva il menu animato per modificare il loop e le dissolvenze.",
  "Alineado a bloques ECC de 16 sectores. La autoría ajusta el corte de capa al PGC más cercano durante la grabación.": "Allineato a blocchi ECC di 16 settori. L’authoring adatta il cambio layer al PGC più vicino durante la masterizzazione.",
  "Arrastra para mover · tiradores para redimensionar · coordenadas pares y separación mínima de 4 px.": "Trascina per spostare · maniglie per ridimensionare · coordinate pari e distanza minima di 4 px.",
  "Añade un menú al proyecto o abre la pestaña Menú desde un proyecto Blu-ray/AVCHD.": "Aggiungi un menu al progetto o apri la scheda Menu da un progetto Blu-ray/AVCHD.",
  "Añade un vídeo desde la biblioteca de medios o elige un episodio en la secuencia.": "Aggiungi un video dalla libreria multimediale o scegli un episodio nella sequenza.",
