  "Comprueba las herramientas externas que usan DVD, AVCHD y Blu-ray.": "Controlla gli strumenti esterni usati da DVD, AVCHD e Blu-ray.",
  "Crea o abre un proyecto para importar medios.": "Crea o apri un progetto per importare contenuti multimediali.",
  "Crea un menú para configurar su bucle, fundidos y botones de vídeo en DVD o HD.": "Crea un menu per configurare loop, dissolvenze e pulsanti video in DVD o HD.",
  "Crea un proyecto DVD-Video o Blu-ray/AVCHD para probar la navegación interactiva.": "Crea un progetto DVD-Video o Blu-ray/AVCHD per provare la navigazione interattiva.",
  "Crea un proyecto DVD-Video para ver el flujo de la máquina virtual.": "Crea un progetto DVD-Video per vedere il flusso della macchina virtuale.",
  "DVD-Video admite hasta 8 pistas de audio y 32 subimágenes; AVCHD y Blu-ray priorizan la primera pista AC-3. Mantén una pista como predeterminada y usa desfases de ±10 s para corregir desincronizaciones.": "DVD-Video supporta fino a 8 tracce audio e 32 sottotitoli grafici; AVCHD e Blu-ray privilegiano la prima traccia AC-3. Mantieni una traccia come predefinita e usa ritardi di ±10 s per correggere la desincronizzazione.",
  "DVD-Video universal o AVCHD/Blu-ray HD con menús HDMV interactivos.": "DVD-Video universale o AVCHD/Blu-ray HD con menu HDMV interattivi.",
  "El clip se repite en bucle y se codifica en el menú HD o DVD animado.": "Il clip viene riprodotto in loop e codificato nel menu HD o DVD animato.",
  "El menú estático se muestra indefinidamente. Actívalo para definir un bucle con entrada/salida y música.": "Il menu statico viene mostrato a tempo indefinito. Attivalo per definire un loop con punti di ingresso/uscita e musica.",
  "El plan se calculará automáticamente al generar el disco.": "Il piano verrà calcolato automaticamente durante la creazione del disco.",
  "El promedio global se mantiene; los bits se redistribuyen.": "La media globale viene mantenuta; i bit vengono ridistribuiti.",
  "El simulador usa el grafo de navegación calculado por Rust, incluidos los overrides del inspector y las acciones de cada botón.": "Il simulatore usa il grafo di navigazione calcolato da Rust, incluse le sostituzioni dell’ispettore e le azioni di ogni pulsante.",
  "Elige un episodio en la secuencia para editar sus pistas de audio y subtítulos.": "Scegli un episodio nella sequenza per modificarne le tracce audio e sottotitoli.",
  "Este proyecto AVCHD no tiene menús y se reproduce en continuo. Añade un menú para compilar Interactive Graphics HDMV.": "Questo progetto AVCHD non ha menu e viene riprodotto in continuo. Aggiungi un menu per compilare HDMV Interactive Graphics.",
  "Este proyecto no tiene menús. Cambia a DVD-Video para diseñar uno.": "Questo progetto non ha menu. Passa a DVD-Video per progettarne uno.",
