  "La duración del menú se sincroniza con el proyecto. La composición combina el fondo, la música y los fragmentos de vídeo de los botones.": "La durata del menu è sincronizzata con il progetto. La composizione combina sfondo, musica e frammenti video dei pulsanti.",
